def subtract(a, b):
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])

        return merged

    # Merge intervals in both a and b
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []
    if not b_merged:
        return a_merged

    result = []

    for a_start, a_end in a_merged:
        current = a_start

        for b_start, b_end in b_merged:
            if b_end <= current or b_start >= a_end:
                # b interval doesn't overlap with current range
                continue

            if current < b_start:
                # Add the part before b_start
                result.append([current, b_start])

            # Move current past this b interval
            current = max(current, b_end)

            if current >= a_end:
                break

        if current < a_end:
            result.append([current, a_end])

    return result

